body.script:
//
					const cfg   = document.getElementById('cfg').dataset;
					const ASSET = cfg.asset;
					// Server-rendered `?as_of=` from the page's own URL (see
					// time_machine_chart's own docstring) — pre-fills the "As
					// Of" input so a specific historical view is bookmarkable.
					// Empty string (not set) means "start at now", same as a
					// bare /tm/<asset> visit.
					const INITIAL_AS_OF = cfg.asOf || '';
					// Coinbase spot, same symbol convention /4l/<asset>
					// uses (server-side _COINBASE_SYMBOL_MAP).
					const COINBASE_SYMBOL = { BTC: 'BTC-USD', ETH: 'ETH-USD' }[ASSET] || (ASSET + '-USD');
					document.getElementById('exchange-label').textContent = 'Coinbase · ' + COINBASE_SYMBOL;

					// "As Of" — the single moment this whole page is frozen
					// at. AS_OF_ISO is always "YYYY-MM-DDTHH:MM:SS" (seconds
					// forced to :00 client-side — the <input type="datetime-
					// local">'s own .value has no seconds — so the server's
					// _parse_as_of_param (main.py) always gets a fully-formed
					// ISO string regardless of Python's own fromisoformat
					// version quirks around omitted seconds). Every fetch on
					// this page appends `&as_of=` + this value.
					let AS_OF_ISO = null;

					function pad(n) { return String(n).padStart(2, '0'); }

					// Formats a JS Date as the UTC "YYYY-MM-DDTHH:MM" string
					// <input type="datetime-local"> expects for its own
					// .value/default — the input has no timezone concept of
					// its own, so this addon's usual UTC-anchored convention
					// is applied by simply reading the UTC getters, not the
					// local ones.
					function toDatetimeLocalUTC(date) {
						return date.getUTCFullYear() + '-' + pad(date.getUTCMonth() + 1) + '-' + pad(date.getUTCDate())
							+ 'T' + pad(date.getUTCHours()) + ':' + pad(date.getUTCMinutes());
					}

					// Europe/Berlin's current UTC offset in seconds (Berlin -
					// UTC, positive), DST-aware (CET/CEST) via Intl's own
					// timezone data rather than a fixed UTC+1/+2 guess — same
					// "diff two toLocaleString renderings of the same instant"
					// idiom the page-wide `tzOffset` above uses, just for
					// Berlin instead of the viewer's own browser zone.
					function berlinOffsetSeconds(refDate) {
						const utc = new Date(refDate.toLocaleString('en-US', { timeZone: 'UTC' }));
						const berlin = new Date(refDate.toLocaleString('en-US', { timeZone: 'Europe/Berlin' }));
						return (berlin - utc) / 1000;
					}

					// The page's own default "As Of" when no `?as_of=` was
					// given on the URL — today's date at 15:30 Europe/Berlin
					// local time, not the exact current instant (that's what
					// the "Now" button is for). Uses BERLIN's own calendar
					// day (via toLocaleDateString('en-CA', ...), which yields
					// "YYYY-MM-DD"), not the browser's or UTC's, since those
					// can disagree with Berlin's "today" for part of the day
					// near midnight. Builds a UTC instant for 15:30 on that
					// same calendar day, then shifts it back by Berlin's own
					// current offset so the result is the real UTC moment
					// that reads as 15:30 on a Berlin clock.
					function defaultAsOfBerlin1530() {
						const now = new Date();
						const offsetSec = berlinOffsetSeconds(now);
						const [y, m, d] = now.toLocaleDateString('en-CA', { timeZone: 'Europe/Berlin' }).split('-').map(Number);
						const guessUTC = Date.UTC(y, m - 1, d, 15, 30, 0);
						return new Date(guessUTC - offsetSec * 1000);
					}

					function setAsOfInput(value) {
						document.getElementById('as-of-input').value = value;
						// Normalized to exactly "YYYY-MM-DDTHH:MM:SS" regardless
						// of whether `value` already carries seconds (e.g. a
						// server-rendered `?as_of=` from the page's own URL,
						// which isn't guaranteed to match the plain "YYYY-MM-
						// DDTHH:MM" shape the <input>'s own .value getter always
						// produces) — sliced to the first 16 chars (dropping any
						// existing seconds) before re-appending ':00', so this
						// never produces a malformed double-seconds string.
						AS_OF_ISO = value.slice(0, 16) + ':00';
					}

					// "Timeframe" dropdown — same options/defaults as /4l/<asset>.
					let INTERVAL = '1d';
					const klineUrl = (iv, limit) =>
						'/api/klines-coinbase/' + ASSET + '?interval=' + iv + '&limit=' + limit + '&as_of=' + encodeURIComponent(AS_OF_ISO);

					// "Expiry" dropdown — which expiry's trades feed the 4
					// gamma legs, reloaded from /api/expiries/<asset>?as_of=
					// (dankbit.bands._distinct_expirations_asof — expiries that
					// had already traded and hadn't yet expired as of AS_OF_ISO,
					// unlike /4l/<asset>'s own live-only _distinct_expirations)
					// every time As Of changes, not just once at page load.
					let SELECTED_INSTRUMENT = null;

					// "Window" dropdown — trailing-hours trade window fed into
					// that expiry's trades, ending at AS_OF_ISO instead of
					// "now" — same choice set/semantics as /4l/<asset>'s own
					// (see FOUR_LEG_WINDOW_HOURS_CHOICES/_auto_window_hours in
					// main.py), just relative to a past moment.
					let WINDOW_HOURS = 'all';
					let autoResolvedHours = null;

					// "Cumulative" checkbox — off by default. When checked,
					// /api/four-leg-gamma's own `?cumulative=1` (see
					// four_leg_gamma_json in main.py) switches the selected
					// Expiry from an ISOLATED single-instrument trade domain
					// to a CUMULATIVE one spanning every instrument whose own
					// expiration falls between AS_OF_ISO and the selected
					// expiry's own expiration, inclusive — the Window
					// dropdown's trailing-hours filter still applies on top,
					// same as the isolated path.
					let CUMULATIVE = false;

					const fourLegGammaUrl = () =>
						'/api/four-leg-gamma/' + ASSET + '?instrument=' + SELECTED_INSTRUMENT + '&hours=' + WINDOW_HOURS
						+ '&as_of=' + encodeURIComponent(AS_OF_ISO)
						+ (CUMULATIVE ? '&cumulative=1' : '');

					let tradeCount = null;

					// Same browser-local-timezone shift every other TV chart page
					// in this addon applies — Lightweight Charts always renders
					// epoch seconds as UTC wall-clock time, so every timestamp fed
					// into the chart is pre-shifted by the viewer's own current
					// UTC offset first.
					const tzOffset = (() => {
						let zone;
						try {
							zone = Intl.DateTimeFormat().resolvedOptions().timeZone;
						} catch (e) {
							return 0;
						}
						const d = new Date();
						const utc = new Date(d.toLocaleString('en-US', { timeZone: 'UTC' }));
						const local = new Date(d.toLocaleString('en-US', { timeZone: zone }));
						return (local - utc) / 1000;
					})();

					const THEME_STORAGE_KEY = 'dankbit_theme';
					let DARK_MODE = localStorage.getItem(THEME_STORAGE_KEY) === 'dark';
					function rulerColor() { return DARK_MODE ? '#aaaaaa' : '#555555'; }

					// "Settings" button/dialog — user-pickable colors for this
					// page's own 4 gamma-leg lines, persisted per-browser under
					// a key completely independent of /4l/<asset>'s own
					// 'dankbit_4l_chart_colors' and the Delta Chart's
					// 'dankbit_chart_colors', since Time Machine is its own
					// page with its own settings.
					const COLOR_STORAGE_KEY = 'dankbit_tm_chart_colors';
					const DEFAULT_COLORS = { bcg: '#000000', bpg: '#000000', scg: '#fb8c00', spg: '#fb8c00' };
					let chartColors = Object.assign({}, DEFAULT_COLORS);
					try {
						const savedColors = JSON.parse(localStorage.getItem(COLOR_STORAGE_KEY) || '{}');
						Object.keys(DEFAULT_COLORS).forEach(key => {
							if (savedColors[key]) chartColors[key] = savedColors[key];
						});
					} catch (e) { /* malformed stored value — fall back to defaults */ }
					// Average of the 4 gamma legs' own price levels — fixed
					// light violet (dashed line), same "gamma" color
					// association this addon uses elsewhere — not part of the
					// "Chart Appearance" color picker above (that modal only
					// covers the 4 raw BCG/BPG/SCG/SPG lines).
					const AVG_GAMMA_COLOR = '#c9a0dc';

					document.getElementById('theme-select').value = DARK_MODE ? 'dark' : 'light';
					document.body.classList.toggle('dark', DARK_MODE);

					// Watermark — this page only (not /4l/<asset> or the
					// Delta Chart), via Lightweight Charts v4's own built-in
					// `watermark` chart option (drawn directly onto the
					// chart's own canvas, so it's properly clipped/resized
					// along with everything else — not a hand-rolled DOM
					// overlay). Fixed gray, deliberately NOT theme-reactive
					// (unlike every other themed chart option on this page)
					// — a light/dark-switching black-ish/white-ish color
					// went invisible in practice (white-on-white in Light,
					// black-on-black in Dark, reported directly), so a
					// single mid-gray at moderate alpha is used instead,
					// which reads against both a white and a black
					// background without needing to track DARK_MODE at all.
					const WATERMARK_TEXT = 'Dankbit Time Machine';
					const WATERMARK_COLOR = 'rgba(120,120,120,0.35)';

					const chart = LightweightCharts.createChart(document.getElementById('chart-container'), {
						width: window.innerWidth, height: window.innerHeight,
						layout: {
							background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
							textColor: DARK_MODE ? '#d1d4dc' : '#333333',
						},
						grid: { vertLines: { visible: false }, horzLines: { visible: false } },
						crosshair: { mode: LightweightCharts.CrosshairMode.Normal, horzLine: { labelBackgroundColor: 'blue' } },
						rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc', timeVisible: true, secondsVisible: false },
						watermark: { visible: true, text: WATERMARK_TEXT, fontSize: 36, color: WATERMARK_COLOR, horzAlign: 'center', vertAlign: 'center' },
						localization: {
							timeFormatter: ts => new Date(ts * 1000).toLocaleString('de-DE', {
								timeZone: 'UTC',
								month: 'short', day: 'numeric',
								hour: '2-digit', minute: '2-digit',
							}),
						},
					});

					window.addEventListener('resize', () => {
						chart.resize(window.innerWidth, window.innerHeight);
					});

					const series = chart.addCandlestickSeries({
						upColor: '#26a69a', downColor: '#ef5350',
						borderVisible: false, wickUpColor: '#26a69a', wickDownColor: '#ef5350',
					});

					// Invisible helper series solely to extend the shared time
					// axis a little past the last historical candle, same
					// mechanism /4l/<asset>'s own futureAxisSeries uses — just
					// breathing room for the 4 gamma price lines' own axis
					// labels, not a claim about real future price action (this
					// page shows a frozen past moment, not a live forecast).
					const futureAxisSeries = chart.addLineSeries({
						color: 'rgba(0,0,0,0)', lineWidth: 1,
						lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});

					// The 4 gamma "lines" are horizontal reference lines at the
					// resolved As-Of/Expiry/Window reading — same
					// createPriceLine() pattern /4l/<asset> uses — redrawn
					// fresh whenever As Of/Expiry/Window changes.
					let bcgPriceLine = null, bpgPriceLine = null, scgPriceLine = null, spgPriceLine = null, avgGammaPriceLine = null;

					function setStatus(text) { document.getElementById('status').textContent = text; }

					function tradeCountSuffix() {
						return tradeCount !== null ? '  ·  ' + tradeCount + ' trades' : '';
					}

					function hoursLabel(hours) {
						if (hours >= 24 && hours % 24 === 0) return (hours / 24) + 'd';
						return hours + 'h';
					}
					function windowLabel() {
						if (WINDOW_HOURS === 'all') return 'all trades';
						if (WINDOW_HOURS === 'auto') {
							return autoResolvedHours !== null
								? 'Auto → ' + hoursLabel(autoResolvedHours) + ' trailing window'
								: 'Auto trailing window';
						}
						return hoursLabel(WINDOW_HOURS) + ' trailing window';
					}

					function statusText() {
						return (SELECTED_INSTRUMENT || ASSET) + ' · Four Leg Gamma (Time Machine, ' + windowLabel() + ')'
							+ (CUMULATIVE ? ' · Cumulative (As Of → Expiry)' : '')
							+ '  ·  As of ' + (AS_OF_ISO || '?') + ' UTC' + tradeCountSuffix();
					}

					function onToggleCumulative() {
						CUMULATIVE = document.getElementById('cumulative-toggle').checked;
						refreshFourLegGamma();
					}

					function showSpinner() { document.getElementById('spinner').style.display = 'block'; }
					function hideSpinner() { document.getElementById('spinner').style.display = 'none'; }

					function toCandle(k) {
						return { time: Math.floor(k.t / 1000) + tzOffset, open: parseFloat(k.o), high: parseFloat(k.h), low: parseFloat(k.l), close: parseFloat(k.c) };
					}

					let realCandles = [];

					// Same per-timeframe visible-window convention /4l/<asset>'s
					// own TF_WINDOW uses.
					const TF_WINDOW = { '15m': 5, '1h': 30, '4h': 15, '1d': 365 };
					const INTERVAL_SECONDS = { '15m': 15 * 60, '1h': 3600, '4h': 4 * 3600, '1d': 86400 };
					const FUTURE_MARGIN_DAYS = 5;

					function applyVisibleRange() {
						if (!realCandles.length) return;
						const days = TF_WINDOW[INTERVAL] || 15;
						const futureEdge = realCandles[realCandles.length - 1].time + FUTURE_MARGIN_DAYS * 86400;
						chart.timeScale().setVisibleRange({ from: futureEdge - days * 86400, to: futureEdge });
					}

					function rebuildSeriesData() {
						series.setData(realCandles);

						const intervalSec = INTERVAL_SECONDS[INTERVAL] || 3600;
						const lastClose = realCandles.length ? realCandles[realCandles.length - 1].close : 0;
						const lastTime = realCandles.length
							? realCandles[realCandles.length - 1].time
							: (Math.floor(Date.now() / 1000) + tzOffset);
						const count = Math.round(FUTURE_MARGIN_DAYS * 86400 / intervalSec);
						const futureTicks = [];
						for (let i = 1; i <= count; i++) {
							futureTicks.push({ time: lastTime + i * intervalSec, value: lastClose });
						}
						futureAxisSeries.setData(futureTicks);
					}

					function resetChartView() {
						chart.priceScale('right').applyOptions({ autoScale: true });
						applyVisibleRange();
					}

					const contextMenu = document.getElementById('context-menu');

					function hideContextMenu() {
						contextMenu.style.display = 'none';
					}

					function showContextMenu(x, y) {
						contextMenu.style.display = 'block';
						const maxX = window.innerWidth - contextMenu.offsetWidth - 4;
						const maxY = window.innerHeight - contextMenu.offsetHeight - 4;
						contextMenu.style.left = Math.min(x, maxX) + 'px';
						contextMenu.style.top = Math.min(y, maxY) + 'px';
					}

					function onResetChartViewClick() {
						resetChartView();
						hideContextMenu();
					}

					const chartContainerEl = document.getElementById('chart-container');
					chartContainerEl.addEventListener('contextmenu', e => {
						e.preventDefault();
						showContextMenu(e.clientX, e.clientY);
					});
					document.addEventListener('contextmenu', e => {
						if (!chartContainerEl.contains(e.target)) hideContextMenu();
					});
					document.addEventListener('click', hideContextMenu);
					window.addEventListener('resize', hideContextMenu);
					window.addEventListener('scroll', hideContextMenu, true);

					async function loadCandles() {
						const resp = await (await fetch(klineUrl(INTERVAL, 500))).json();
						const klines = (resp.result || []).slice().reverse();
						realCandles = klines.map(toCandle);
						rebuildSeriesData();
						applyVisibleRange();
					}

					async function setTf(iv) {
						INTERVAL = iv;
						await loadCandles();
						setStatus(statusText());
					}

					function updateInstrumentLabel() {
						document.getElementById('instrument-label').textContent = SELECTED_INSTRUMENT || '';
					}

					async function setExpiry(instr) {
						SELECTED_INSTRUMENT = instr;
						updateInstrumentLabel();
						await refreshFourLegGamma();
					}

					// Populates the "Expiry" dropdown from every expiry that had
					// already traded and hadn't yet expired as of AS_OF_ISO (see
					// dankbit.bands._distinct_expirations_asof, /api/expiries'
					// own `?as_of=` branch) — reloaded every time As Of changes,
					// unlike /4l/<asset>'s own loadExpiries() (called once at
					// page load only, since that page's "now" never moves).
					// Selects the soonest (first) entry by default.
					async function loadExpiries() {
						const select = document.getElementById('expiry-select');
						const data = await (await fetch('/api/expiries/' + ASSET + '?as_of=' + encodeURIComponent(AS_OF_ISO))).json();
						const expiries = data.expiries || [];
						select.innerHTML = '';
						expiries.forEach(instr => {
							const opt = document.createElement('option');
							opt.value = instr;
							opt.textContent = instr;
							select.appendChild(opt);
						});
						SELECTED_INSTRUMENT = expiries.length ? expiries[0] : null;
						if (SELECTED_INSTRUMENT) select.value = SELECTED_INSTRUMENT;
						updateInstrumentLabel();
					}

					async function setWindow(hours) {
						WINDOW_HOURS = (hours === 'all' || hours === 'auto') ? hours : parseInt(hours, 10);
						autoResolvedHours = null;
						await refreshFourLegGamma();
						setStatus(statusText());
					}

					// Rounds and abbreviates large raw dollar-gamma values —
					// same convention /4l/<asset>'s own formatAbbreviated() uses.
					function formatAbbreviated(value) {
						const sign = value < 0 ? '-' : '';
						const abs = Math.abs(value);
						if (abs >= 1e6) return sign + Math.round(abs / 1e6).toLocaleString('en-US') + 'M';
						if (abs >= 1e3) return sign + Math.round(abs / 1e3).toLocaleString('en-US') + 'K';
						return sign + Math.round(abs).toLocaleString('en-US');
					}

					// Fetches and redraws the 4 gamma-leg lines (+ AVG) for the
					// current SELECTED_INSTRUMENT/WINDOW_HOURS as of AS_OF_ISO —
					// same shape as /4l/<asset>'s own refreshFourLegGamma(),
					// minus the AVG N+1 forward-looking line (which has no clean
					// meaning for a frozen past moment) and minus the periodic
					// re-poll (this only ever runs in direct response to a
					// control change on this page).
					async function refreshFourLegGamma() {
						if (!SELECTED_INSTRUMENT) {
							if (bcgPriceLine) { series.removePriceLine(bcgPriceLine); bcgPriceLine = null; }
							if (bpgPriceLine) { series.removePriceLine(bpgPriceLine); bpgPriceLine = null; }
							if (scgPriceLine) { series.removePriceLine(scgPriceLine); scgPriceLine = null; }
							if (spgPriceLine) { series.removePriceLine(spgPriceLine); spgPriceLine = null; }
							if (avgGammaPriceLine) { series.removePriceLine(avgGammaPriceLine); avgGammaPriceLine = null; }
							tradeCount = null;
							setStatus(statusText());
							return;
						}
						showSpinner();
						try {
							const data = await (await fetch(fourLegGammaUrl())).json();
							const points = data.points || [];
							const latest = points.length ? points[points.length - 1] : null;

							autoResolvedHours = typeof data.window_hours === 'number' ? data.window_hours : null;
							tradeCount = latest ? latest.trade_count : 0;
							setStatus(statusText());

							if (bcgPriceLine) { series.removePriceLine(bcgPriceLine); bcgPriceLine = null; }
							if (bpgPriceLine) { series.removePriceLine(bpgPriceLine); bpgPriceLine = null; }
							if (scgPriceLine) { series.removePriceLine(scgPriceLine); scgPriceLine = null; }
							if (spgPriceLine) { series.removePriceLine(spgPriceLine); spgPriceLine = null; }
							if (avgGammaPriceLine) { series.removePriceLine(avgGammaPriceLine); avgGammaPriceLine = null; }
							if (!latest) {
								return;
							}

							if (latest.bcg_price) {
								bcgPriceLine = series.createPriceLine({
									price: latest.bcg_price, color: chartColors.bcg, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: chartColors.bcg,
									title: 'LC ' + formatAbbreviated(latest.bcg_value),
								});
							}
							if (latest.bpg_price) {
								bpgPriceLine = series.createPriceLine({
									price: latest.bpg_price, color: chartColors.bpg, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: chartColors.bpg,
									title: 'LP ' + formatAbbreviated(latest.bpg_value),
								});
							}
							if (latest.scg_price) {
								const smartLiqCall = Math.abs(latest.bcg_value) + Math.abs(latest.scg_value);
								scgPriceLine = series.createPriceLine({
									price: latest.scg_price, color: chartColors.scg, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: chartColors.scg,
									title: 'SC ' + formatAbbreviated(latest.scg_value) + ' | ' + formatAbbreviated(smartLiqCall),
								});
							}
							if (latest.spg_price) {
								const smartLiqPut = Math.abs(latest.bpg_value) + Math.abs(latest.spg_value);
								spgPriceLine = series.createPriceLine({
									price: latest.spg_price, color: chartColors.spg, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: chartColors.spg,
									title: 'SP ' + formatAbbreviated(latest.spg_value) + ' | ' + formatAbbreviated(smartLiqPut),
								});
							}
							const gammaLegs = [
								{ price: latest.bcg_price, value: latest.bcg_value },
								{ price: latest.bpg_price, value: latest.bpg_value },
								{ price: latest.scg_price, value: latest.scg_value },
								{ price: latest.spg_price, value: latest.spg_value },
							].filter(leg => leg.price);
							if (gammaLegs.length) {
								const avgGammaPrice = gammaLegs.reduce((a, leg) => a + leg.price, 0) / gammaLegs.length;
								const avgGammaValue = gammaLegs.reduce((a, leg) => a + leg.value, 0) / gammaLegs.length;
								avgGammaPriceLine = series.createPriceLine({
									price: avgGammaPrice, color: AVG_GAMMA_COLOR, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Dashed,
									axisLabelVisible: true, axisLabelColor: AVG_GAMMA_COLOR,
									title: 'AVG ' + formatAbbreviated(avgGammaValue),
								});
							}
						} finally {
							hideSpinner();
						}
					}

					function applyTheme() {
						document.body.classList.toggle('dark', DARK_MODE);
						chart.applyOptions({
							layout: {
								background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
								textColor: DARK_MODE ? '#d1d4dc' : '#333333',
							},
							rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
							timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						});
					}

					function onThemeChange() {
						DARK_MODE = document.getElementById('theme-select').value === 'dark';
						localStorage.setItem(THEME_STORAGE_KEY, DARK_MODE ? 'dark' : 'light');
						applyTheme();
					}

					function openSettingsModal() {
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) input.value = chartColors[key];
						});
						document.getElementById('settings-modal').style.display = 'flex';
					}

					function closeSettingsModal() {
						document.getElementById('settings-modal').style.display = 'none';
					}

					function saveChartColors() {
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) chartColors[key] = input.value;
						});
						localStorage.setItem(COLOR_STORAGE_KEY, JSON.stringify(chartColors));
						refreshFourLegGamma();
						closeSettingsModal();
					}

					function resetChartColors() {
						chartColors = Object.assign({}, DEFAULT_COLORS);
						localStorage.removeItem(COLOR_STORAGE_KEY);
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) input.value = chartColors[key];
						});
						refreshFourLegGamma();
					}

					let rulerActive = false;
					let rulerPrice1 = null;
					let rulerLines  = [];

					function toggleRuler() {
						rulerActive = !rulerActive;
						document.getElementById('ruler-btn').classList.toggle('active', rulerActive);
						rulerLines.forEach(l => series.removePriceLine(l));
						rulerLines = [];
						rulerPrice1 = null;
						const info = document.getElementById('ruler-info');
						info.style.display = 'none';
						info.textContent = '';
					}

					chart.subscribeClick(param => {
						if (!rulerActive || !param.point) return;
						const price = series.coordinateToPrice(param.point.y);
						if (rulerPrice1 === null) {
							rulerPrice1 = price;
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: DARK_MODE ? '#e8e8e8' : '#000000', title: '①',
							}));
						} else {
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: DARK_MODE ? '#e8e8e8' : '#000000', title: '②',
							}));
							const pct = ((price - rulerPrice1) / rulerPrice1 * 100);
							const sign = pct >= 0 ? '+' : '';
							const info = document.getElementById('ruler-info');
							info.style.display = 'block';
							info.textContent = rulerPrice1.toFixed(0) + ' → ' + price.toFixed(0) + '   ' + sign + pct.toFixed(2) + '%';
							rulerPrice1 = null;
						}
					});

					// Re-runs every fetch on this page against the current
					// AS_OF_ISO — called whenever the "As Of" input changes or
					// the "Now" button is pressed. Candles/Expiries/gamma legs
					// all depend on AS_OF_ISO, so all 3 are re-fetched together
					// (unlike setTf/setExpiry/setWindow, which each only touch
					// the one thing they control).
					async function reloadForAsOf() {
						showSpinner();
						try {
							await loadCandles();
							await loadExpiries();
							await refreshFourLegGamma();
							setStatus(statusText());
						} catch (e) {
							setStatus('Error: ' + e.message);
						} finally {
							hideSpinner();
						}
					}

					function onAsOfChange() {
						const value = document.getElementById('as-of-input').value;
						if (!value) return;
						setAsOfInput(value);
						reloadForAsOf();
					}

					function jumpToNow() {
						setAsOfInput(toDatetimeLocalUTC(new Date()));
						reloadForAsOf();
					}

					async function init() {
						try {
							setAsOfInput(INITIAL_AS_OF || toDatetimeLocalUTC(defaultAsOfBerlin1530()));
							await loadCandles();
							await loadExpiries();
							await refreshFourLegGamma();
							setStatus(statusText());
						}
						catch (e) { setStatus('Error: ' + e.message); }
					}
					init();
				//
